      maxDistance: 32
    });
    if (!furnaceBlock) throw new Error("FURNACE_NOT_AVAILABLE_AFTER_PLACEMENT");
  }
  const fuelCandidates = ["coal", "oak_planks", "birch_planks", "oak_log", "birch_log", "cherry_log"];
  let fuelName = null;
  for (const candidate of fuelCandidates) {
    if (countItem(candidate) >= neededSmelts) {
      fuelName = candidate;
      break;
    }
  }
  if (!fuelName) throw new Error("NOT_ENOUGH_FUEL_FOR_SMELTING");
  const ingotsBefore = countItem(ingotName);
  const rawBefore = countItem(rawName);
  await smeltItem(bot, rawName, fuelName, neededSmelts);
  const ingotsAfter = countItem(ingotName);
  const rawAfter = countItem(rawName);
  if (ingotsAfter < targetIngots) throw new Error("SMELTING_FAILED_TO_REACH_TARGET");
  if (rawBefore - rawAfter < neededSmelts) throw new Error("RAW_IRON_NOT_CONSUMED_AS_EXPECTED");
  if (ingotsAfter - ingotsBefore < neededSmelts) throw new Error("IRON_INGOT_OUTPUT_INSUFFICIENT");
  return {
    success: true
  };
}

